import { Buffer } from 'node:buffer';
import { constants } from 'node:fs';
import { open } from 'node:fs/promises';
import { REAL_EXPERIMENT_BYTES } from './realExperiments';

const CHUNK_BYTES = 64 * 1024;
/** File descriptor checks and capped reads also bound files that grow after fstat.
 * No provider readFile, writes, or upstream/path details are exposed.
 */
export async function readBoundedExperimentFile(
  path: string,
): Promise<Uint8Array> {
  let handle: Awaited<ReturnType<typeof open>> | undefined;
  try {
    if (typeof path !== 'string' || !path || path.includes('\u0000'))
      throw new Error();
    handle = await open(
      path,
      constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK,
    );
    const stat = await handle.stat();
    if (
      !stat.isFile() ||
      !Number.isSafeInteger(stat.size) ||
      stat.size < 0 ||
      stat.size > REAL_EXPERIMENT_BYTES
    )
      throw new Error();
    const chunks: Buffer[] = [];
    let total = 0;
    while (true) {
      // One sentinel byte detects growth beyond the cap, without a full allocation.
      const chunk = Buffer.alloc(
        Math.min(CHUNK_BYTES, REAL_EXPERIMENT_BYTES - total + 1),
      );
      const { bytesRead } = await handle.read(chunk, 0, chunk.length, null);
      if (
        !Number.isInteger(bytesRead) ||
        bytesRead < 0 ||
        bytesRead > chunk.length
      )
        throw new Error();
      if (bytesRead === 0) break;
      total += bytesRead;
      if (total > REAL_EXPERIMENT_BYTES) throw new Error();
      chunks.push(chunk.subarray(0, bytesRead));
    }
    const bytes = Buffer.concat(chunks, total);
    await handle.close();
    handle = undefined;
    return bytes;
  } catch {
    throw new Error('invalid_snapshot_file');
  } finally {
    await handle?.close().catch(() => {});
  }
}
import { Buffer } from 'node:buffer';
import { randomUUID } from 'node:crypto';
import * as vscode from 'vscode';
import { readBoundedExperimentFile } from './boundedExperimentRead';
import { exportRealExample } from './realExperimentExports';
import {
  decodeRealExperiment,
  encodeRealExperiment,
  type RealExperiment,
} from './realExperiments';

async function acknowledge(): Promise<boolean> {
  return (
    (await vscode.window.showWarningMessage(
      'Prompts and outputs are explicitly included. Review sensitive data before saving or sharing. No hidden storage, execution or restored authority.',
      { modal: true },
      'Open document',
    )) === 'Open document'
  );
}
/** Native Save As owns destination and overwrite. Do not claim a saved result. */
export async function saveRealExchange(
  snapshot: RealExperiment,
): Promise<void> {
  const content = Buffer.from(encodeRealExperiment(snapshot)).toString('utf8');
  if (!(await acknowledge())) return;
  const document = await vscode.workspace.openTextDocument({
    language: 'json',
    content,
  });
  await vscode.window.showTextDocument(document, { preview: false });
  await vscode.commands.executeCommand('workbench.action.files.saveAs');
}
/** Never return imported data to an invocation controller. */
export async function reviewRealSnapshot(): Promise<void> {
  const uris = await vscode.window.showOpenDialog({
    title: 'Load snapshot (review only)',
    canSelectMany: false,
    canSelectFiles: true,
    canSelectFolders: false,
    filters: { 'Snapshot JSON': ['json'] },
  });
  if (uris?.length !== 1) return;
  const uri = uris[0];
  if (uri.scheme !== 'file') throw new Error('invalid_snapshot_file');
  const bytes = await readBoundedExperimentFile(uri.fsPath);
  const snapshot = decodeRealExperiment(bytes);
  if (!snapshot) throw new Error('invalid_snapshot_file');
  if (!(await acknowledge())) return;
  const content = Buffer.from(encodeRealExperiment(snapshot)).toString('utf8');
  const scheme = `scaleway-snapshot-${randomUUID()}`;
  const reviewUri = vscode.Uri.parse(`${scheme}:/review-only.json`);
  const provider = vscode.workspace.registerTextDocumentContentProvider(
    scheme,
    { provideTextDocumentContent: () => content },
  );
  let closed: vscode.Disposable | undefined;
  try {
    closed = vscode.workspace.onDidCloseTextDocument((document) => {
      if (document.uri.toString() === reviewUri.toString()) {
        provider.dispose();
        closed?.dispose();
      }
    });
    const document = await vscode.workspace.openTextDocument(reviewUri);
    await vscode.window.showTextDocument(document, { preview: false });
  } catch {
    provider.dispose();
    closed?.dispose();
    throw new Error('snapshot_review_unavailable');
  }
}
export async function exportRealExchange(
  snapshot: RealExperiment,
): Promise<void> {
  const selected = await vscode.window.showQuickPick(
    [
      {
        label: 'Python · source only · mock default',
        language: 'python' as const,
      },
      {
        label: 'TypeScript · source only · mock default',
        language: 'typescript' as const,
      },
    ],
    { title: 'Export example (opens source; never executes)' },
  );
  if (!selected) return;
  const content = exportRealExample(snapshot, selected.language);
  if (!(await acknowledge())) return;
  const document = await vscode.workspace.openTextDocument({
    language: selected.language,
    content,
  });
  await vscode.window.showTextDocument(document, { preview: false });
}",
  "import { Buffer } from 'node:buffer';

export const REAL_OUTPUT_BYTES = 2 * 1024 * 1024;
// Allows worst-case JSON escaping of a transport-sized output, but remains bounded.
export const REAL_EXPERIMENT_BYTES = 16 * 1024 * 1024;
export interface RealService {
  readonly kind: 'serverless' | 'dedicated';
  readonly organizationId: string;
  readonly projectId: string;
  readonly modelId: string;
  readonly modelName: string;
  readonly destination: string;
  readonly authentication: 'iam' | 'disabled';
  readonly region?: 'fr-par';
  readonly deploymentId?: string;
  readonly endpointId?: string;
  readonly endpointUrl?: string;
}
export interface RealUsage {
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly totalTokens: number;
  readonly cachedInputTokens?: number;
}
export const REAL_FAILURE_CODES = [
  'endpoint_policy',
  'invalid_input',
  'invalid_credentials',
  'aborted',
  'timeout',
  'idle_timeout',
  'http_error',
  'network_error',
  'provider_error',
  'invalid_stream',
  'model_mismatch',
  'response_too_large',
  'frame_too_large',
  'unexpected_eof',
  'callback_error',
  'access_denied',
] as const;
export interface RealFailure {
  readonly code: (typeof REAL_FAILURE_CODES)[number];
  readonly status?: number;
}
/** Only allowlisted codes and HTTP error status; never messages or bodies. */
export function sanitizeRealFailure(
  code: unknown,
  status?: unknown,
): RealFailure {
  const safeCode =
    REAL_FAILURE_CODES.find((candidate) => candidate === code) ??
    'access_denied';
  return {
    code: safeCode,
    ...(safeCode === 'http_error' &&
    typeof status === 'number' &&
    Number.isInteger(status) &&
    status >= 400 &&
    status <= 599
      ? { status }
      : {}),
  };
}
export interface RealCost {
  readonly actual: 'unknown';
  readonly billing: 'token' | 'deployment-duration';
  readonly publicEstimate?: Readonly<{
    source: 'public-catalog';
    currency: 'EUR';
    display: string;
    retrievedAt: 'unknown' | string;
  }>;
  readonly estimate?: Readonly<{
    source: 'public-catalog';
    currency: 'EUR';
    amount: number;
    retrievedAt: string;
  }>;
}
export interface RealExperiment {
  readonly version: 1;
  readonly mode: 'real-provider';
  readonly status: 'completed' | 'cancelled' | 'failed' | 'partial';
  readonly timestamp: string;
  readonly service: Readonly<RealService>;
  readonly prompt: string;
  readonly maxTokens: number;
  readonly output: string;
  readonly execution: Readonly<{
    environment: 'local-mock' | 'live';
    billed: 'none' | 'unknown' | 'possible';
    status?: string;
  }>;
  readonly failure?: Readonly<RealFailure>;
  readonly usage?: Readonly<RealUsage>;
  readonly cost?: Readonly<RealCost>;
}
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const MODEL = /^[A-Za-z0-9][A-Za-z0-9._:/-]{0,255}$/;
function keys(
  v: unknown,
  required: string[],
  optional: string[] = [],
